function t(k){return C[locale][k]||C.en[k]||k}function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function translateOpt(s){return locale==="ar"?(OAR[s]||s):locale==="fr"?(OFR[s]||s):s}function optionHtml(rows){return rows.map(([v,s])=>`<option value="${esc(v)}">${esc(s==="—"?"—":translateOpt(s))}</option>`).join("")}
function productName(p){if(locale==="ar")return p.nameAr||p.nameEn||p.id;if(locale==="fr"){try{return window.ZWM_FR_TRANSLATE?window.ZWM_FR_TRANSLATE(p.nameEn||p.id):(p.nameEn||p.id)}catch{}}return p.nameEn||p.nameAr||p.id}
function variantName(v){if(!v)return"";if(locale==="ar")return v.sizeAr||v.sizeEn||"";return v.sizeEn||v.sizeAr||""}
function applyLocale(){locale=getLocale();D.documentElement.lang=locale;D.documentElement.dir=locale==="ar"?"rtl":"ltr";if($("productSearchState"))$("productSearchState").textContent=t("loading");qa("[data-t]").forEach(el=>{const k=el.dataset.t;if(C[locale][k])el.textContent=C[locale][k]});qa("[data-ph]").forEach(el=>{const k=el.dataset.ph;if(C[locale][k])el.placeholder=C[locale][k]});qa("[data-wholesale-lang]").forEach(b=>b.classList.toggle("is-active",b.dataset.wholesaleLang===locale));$("businessType").innerHTML=optionHtml(OPT.businessType);$("frequency").innerHTML=optionHtml(OPT.frequency);$("approxVolume").innerHTML=optionHtml(OPT.volume);$("firstOrder").innerHTML=optionHtml(OPT.timing);$("supplierStatus").innerHTML=optionHtml(OPT.supplier);$("frequency").value="not_sure";$("firstOrder").value="exploring";$("priorityOptions").innerHTML=PRIORITIES.map(x=>`<label><input type="checkbox" value="${x[0]}"><span>${esc(x[locale==="ar"?2:locale==="fr"?3:1])}</span></label>`).join("");$("contactOptions").innerHTML=CONTACT.map((x,i)=>`<label><input type="radio" name="preferredContact" value="${x[0]}" ${i===0?"checked":""}><span>${esc(x[locale==="ar"?2:locale==="fr"?3:1])}</span></label>`).join("");renderResults();renderSelected();syncSiteShell();renderHistory()}
function localized(path,code=locale){path=path.replace(/^\/(ar|fr)(?=\/|$)/,"")||"/";return code==="en"?path:`/${code}${path}`}
function syncSiteShell(){
  const year=D.querySelector("[data-footer-year]");if(year)year.textContent=String(new Date().getFullYear());
  const cartLink=$("cartButton");if(cartLink)cartLink.setAttribute("href",localized("/shop"));
  const count=$("cartCount");
  if(count){
    let total=0;
    try{
      const raw=JSON.parse(localStorage.getItem("zwm-cart-v5")||"{}");
      total=Object.values(raw||{}).reduce((sum,item)=>sum+Math.max(1,Number(item&&item.qty)||1),0);
    }catch{}
    count.textContent=String(total);
  }
}
function setLanguage(code){try{localStorage.setItem(DRAFT_KEY,JSON.stringify(draftObject()));if(window.ZWM_LOCALE?.set)window.ZWM_LOCALE.set(code);else localStorage.setItem("zwm-locale-v3",code)}catch{}location.assign(window.ZWM_LOCALE?.localePath?window.ZWM_LOCALE.localePath("/wholesale",code):localized("/wholesale",code))}
function loadProducts(){const list=typeof PRODUCTS_DATA!=="undefined"&&Array.isArray(PRODUCTS_DATA)?PRODUCTS_DATA:[];products=list.filter(p=>p&&p.id&&p.nameEn);$("productSearchState").textContent=list.length?"":t("loadFail");renderResults()}
function norm(v){return String(v||"").normalize("NFKD").replace(/[\u064B-\u065F]/g,"").toLowerCase().trim()}
function renderResults(){const host=$("productResults"),state=$("productSearchState");if(!host)return;if(!products.length){host.innerHTML="";state.textContent=t("loadFail");return}const q=norm($("productSearch")?.value),matches=products.filter(p=>!selected.has(p.id)&&(!q||norm([p.nameEn,p.nameAr,p.original,p.category].join(" ")).includes(q))).slice(0,24);if(!matches.length){host.innerHTML="";state.textContent=t("noMatch");return}state.textContent="";host.innerHTML=matches.map(p=>`<button type="button" class="product-result" data-add-product="${esc(p.id)}"><span><strong>${esc(productName(p))}</strong><small>${esc(p.category||"")}</small></span><b aria-hidden="true">+</b></button>`).join("")}
function renderSelected(){const host=$("selectedProducts");$("selectedCount").textContent=String(selected.size);if(!selected.size){host.innerHTML=`<div class="selected-empty">${esc(t("emptySelected"))}</div>`;return}host.innerHTML=[...selected.values()].map(row=>{const p=products.find(x=>x.id===row.productId)||row.product,variants=(p?.variants||[]),variantOpts=[["","—"],...variants.map(v=>[v.id,variantName(v)])].map(([v,n])=>`<option value="${esc(v)}" ${v===row.variantId?"selected":""}>${esc(n)}</option>`).join("");return `<div class="selected-product" data-selected-product="${esc(row.productId)}"><div class="selected-product-name"><strong>${esc(productName(p||{}))}</strong><small>${esc(p?.category||"")}</small></div><label><span>${esc(t("catalogueFormat"))}</span><select data-row-field="variant">${variantOpts}</select></label><label><span>${esc(t("quantity"))}</span><input data-row-field="quantity" type="number" min="0.001" max="1000000" step="0.001" inputmode="decimal" value="${esc(row.quantity)}"></label><label><span>${esc(t("unit"))}</span><select data-row-field="unit">${optionHtml(OPT.units).replace(`value="${row.unit}"`,`value="${row.unit}" selected`)}</select></label><button type="button" class="remove-product" data-remove-product="${esc(row.productId)}" aria-label="${esc(t("remove"))}">×</button></div>`}).join("")}
function addProduct(id){const p=products.find(x=>x.id===id);if(!p||selected.has(id))return;selected.set(id,{productId:id,product:p,variantId:p.variants?.[0]?.id||"",quantity:1,unit:"units"});renderSelected();renderResults();markStarted();track("wholesale_product_added",{product_id:id});saveDraftSoon()}
function updateSelectedFromDom(){qa("[data-selected-product]").forEach(el=>{const row=selected.get(el.dataset.selectedProduct);if(!row)return;row.variantId=el.querySelector('[data-row-field="variant"]')?.value||"";row.quantity=el.querySelector('[data-row-field="quantity"]')?.value||"1";row.unit=el.querySelector('[data-row-field="unit"]')?.value||"units"})}
function markStarted(){if(started)return;started=true;track("wholesale_request_started",{})}
function ensureSubmissionKey(){
  if(submissionKey)return submissionKey;
  if(window.crypto&&typeof window.crypto.randomUUID==="function")submissionKey=window.crypto.randomUUID();
  else{
    const hex=()=>Math.floor(Math.random()*0x10000).toString(16).padStart(4,"0");
    submissionKey=hex()+hex()+"-"+hex()+"-4"+hex().slice(1)+"-"+((8+Math.floor(Math.random()*4)).toString(16))+hex().slice(1)+"-"+hex()+hex()+hex();
  }
  return submissionKey;
}
function authSession(){try{const s=JSON.parse(localStorage.getItem(AUTH_KEY)||"null");return s&&s.access_token?s:null}catch{return null}}
function apiHeaders(){const cfg=window.ZWM_CMS_CONFIG||{},s=authSession(),h={"apikey":cfg.supabasePublishableKey||"","Content-Type":"application/json","Prefer":"return=representation"};if(s?.access_token)h.Authorization="Bearer "+s.access_token;return h}
async function rpc(name,body){const cfg=window.ZWM_CMS_CONFIG||{};if(!cfg.supabaseUrl||!cfg.supabasePublishableKey)throw new Error("service_unavailable");const r=await fetch(String(cfg.supabaseUrl).replace(/\/$/,"")+"/rest/v1/rpc/"+name,{method:"POST",headers:apiHeaders(),body:JSON.stringify(body||{})});const data=await r.json().catch(()=>null);if(!r.ok)throw new Error(data?.message||data?.hint||"request_failed");return data}
function readReceipts(){try{const rows=JSON.parse(localStorage.getItem(HISTORY_KEY)||"[]");return Array.isArray(rows)?rows.filter(x=>x&&x.submissionKey).slice(0,30):[]}catch{return[]}}
function writeReceipts(rows){try{localStorage.setItem(HISTORY_KEY,JSON.stringify(rows.slice(0,30)))}catch{}}
function saveReceipt(row){if(!row?.submissionKey)return;const rows=readReceipts().filter(x=>x.submissionKey!==row.submissionKey);rows.unshift({submissionKey:row.submissionKey,reference:row.reference||"",createdAt:row.createdAt||new Date().toISOString(),businessName:row.businessName||""});writeReceipts(rows)}
function removeReceipt(row){const rows=readReceipts().filter(x=>{if(row?._submissionKey&&x.submissionKey===row._submissionKey)return false;if(row?.reference&&x.reference===row.reference)return false;return true});writeReceipts(rows)}
function requestReferenceFromId(id){const clean=String(id||"").replace(/-/g,"").toUpperCase();return clean?"ZW-B2B-"+clean.slice(0,8):""}
function fmtHistoryDate(v){if(!v)return"—";try{return new Date(v).toLocaleString(locale==="ar"?"ar-LB":locale==="fr"?"fr-LB":"en-LB",{year:"numeric",month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"})}catch{return String(v)}}
function contactLabel(v){const row=CONTACT.find(x=>x[0]===v);return row?row[locale==="ar"?2:locale==="fr"?3:1]:String(v||"—")}
function statusInfo(v){return (STATUS_COPY[locale]||STATUS_COPY.en)[v]||(STATUS_COPY.en[v]||[String(v||"—"),""])}
function historyItemRows(items){return (Array.isArray(items)?items:[]).map(i=>`<li><strong>${esc(i.product_name||"")}</strong><span>${esc(i.variant||"")}${i.quantity!=null?` · ${esc(i.quantity)} ${esc(i.unit||"")}`:""}</span></li>`).join("")}
function renderHistory(){
  const list=$("wholesaleHistoryList"),state=$("wholesaleHistoryState"),signIn=$("wholesaleHistorySignIn");
  if(!list||!state)return;
  const signed=!!authSession()?.access_token;
  if(signIn){signIn.hidden=signed;signIn.href=localized("/account?auth=signin#signin")}
  if(!historyRows.length){list.innerHTML="";state.hidden=false;state.textContent=t("historyEmpty");return}
  state.hidden=true;
  list.innerHTML=historyRows.map(row=>{
    const info=statusInfo(row.status),items=Array.isArray(row.items)?row.items:[],follow=row.next_follow_up_at?fmtHistoryDate(row.next_follow_up_at):"",updated=fmtHistoryDate(row.updated_at||row.created_at),submitted=fmtHistoryDate(row.created_at);
    return `<article class="wholesale-history-card" data-status="${esc(row.status||"new")}" data-wholesale-lead-id="${esc(row.lead_id||"")}" tabindex="-1"><header><div><small>${esc(row.reference||"")}</small><h3>${esc(row.business_name||"")}</h3></div><span class="wholesale-customer-status">${esc(info[0])}</span></header><p class="wholesale-history-next">${esc(info[1])}</p><div class="wholesale-history-meta"><span><b>${esc(t("historySubmitted"))}</b>${esc(submitted)}</span><span><b>${esc(t("historyUpdated"))}</b>${esc(updated)}</span><span><b>${esc(t("historyContact"))}</b>${esc(contactLabel(row.preferred_contact_method))}</span>${follow?`<span><b>${esc(t("historyFollowUp"))}</b>${esc(follow)}</span>`:""}</div><details><summary>${esc(t("historyProducts"))} · ${items.length}</summary><ul>${historyItemRows(items)||`<li>${esc(row.unlisted_products||"—")}</li>`}</ul>${row.notes?`<p>${esc(row.notes)}</p>`:""}</details><div class="wholesale-history-card-actions"><button type="button" class="wholesale-history-delete" data-history-delete="${esc(row.reference||"")}">${esc(t("historyDelete"))}</button></div></article>`
  }).join("");
  queueMicrotask(revealDeepLinkedRequest);
}
function revealDeepLinkedRequest(){
  try{
    const u=new URL(location.href);
    if(u.searchParams.get("notification")!=="wholesale")return;
    const id=u.searchParams.get("id");if(!id)return;
    const card=qa("[data-wholesale-lead-id]").find(el=>el.dataset.wholesaleLeadId===id);
    if(!card)return;
    const details=card.querySelector("details");if(details)details.open=true;
    card.focus({preventScroll:true});card.scrollIntoView({behavior:"smooth",block:"center"});
    u.searchParams.delete("notification");u.searchParams.delete("id");
    history.replaceState(null,"",u.pathname+u.search+u.hash);
  }catch(e){console.warn("Wholesale notification deep link failed",e)}
}
async function deleteHistoryRow(reference,button){const row=historyRows.find(x=>x.reference===reference);if(!row||!window.confirm(t("historyDeleteConfirm")))return;if(button)button.disabled=true;try{if(row.lead_id&&authSession()?.access_token){const hidden=await rpc("hide_my_wholesale_enquiry",{p_lead_id:row.lead_id});if(hidden!==true)throw new Error("history_remove_failed")}removeReceipt(row);historyRows=historyRows.filter(x=>x.reference!==reference);renderHistory()}catch(e){console.warn("Wholesale history removal failed",e);window.alert(t("historyDeleteFail"));if(button)button.disabled=false}}
async function loadHistory(){
  const state=$("wholesaleHistoryState"),refresh=$("refreshWholesaleHistory");if(refresh)refresh.disabled=true;if(state){state.hidden=false;state.textContent=t("historyLoading")}
  try{
    const localRows=(await Promise.all(readReceipts().map(async receipt=>{try{const row=await rpc("get_wholesale_enquiry_status",{p_submission_key:receipt.submissionKey});return row&&row.found!==false?{...row,_submissionKey:receipt.submissionKey}:null}catch{return null}}))).filter(Boolean);
    let accountRows=[];
    if(authSession()?.access_token){try{const rows=await rpc("get_my_wholesale_enquiries",{});if(Array.isArray(rows))accountRows=rows}catch{}}
    const map=new Map();
    [...localRows,...accountRows].forEach(row=>{if(row?.reference){const prior=map.get(row.reference)||{};map.set(row.reference,{...prior,...row,_submissionKey:prior._submissionKey||row._submissionKey||""})}});
    historyRows=[...map.values()].sort((a,b)=>new Date(b.created_at||0)-new Date(a.created_at||0));
    renderHistory();
    return historyRows;
  }finally{if(refresh)refresh.disabled=false}
}
